package com.vivamais.dto;
import com.vivamais.config.*;
import com.vivamais.controller.*;
import com.vivamais.dto.*;
import com.vivamais.repositories.*;
import com.vivamais.security.*;
import com.vivamais.service.*;
import com.vivamais.model.*;

import java.time.*;
import java.util.*;
import jakarta.validation.constraints.*;

public final class ModelosCuidado {
 private ModelosCuidado() {}
 public record Pagina<T>(List<T> items,long total,@com.fasterxml.jackson.annotation.JsonProperty("page") int paginar,int size) {}
 public record CadastroPaciente(@com.fasterxml.jackson.annotation.JsonProperty("displayName") @NotBlank @Size(max=160) String nomeExibicao,@com.fasterxml.jackson.annotation.JsonProperty("modality") @Pattern(regexp="APP|BRACELET_DIARY") @NotNull String modalidade,@Email @Size(max=254) String email,
     @Size(max=14) String cpf, LocalDate dataNascimento, @Size(max=20) String telefone, @Size(max=30) String sexo, @Size(max=500) String endereco) {}
 public record DadosPessoaisPaciente(UUID idPaciente, String nomeCompleto, String cpf, LocalDate dataNascimento, String emailContato, String telefone, String sexo, String endereco, int versao) {}
 public record AtualizacaoDadosPessoais(@NotBlank @Size(max=160) String nomeCompleto, @Size(max=14) String cpf, LocalDate dataNascimento, @Email @Size(max=254) String emailContato, @Size(max=20) String telefone, @Size(max=30) String sexo, @Size(max=500) String endereco, @NotNull @Min(0) Integer versao, @Size(max=72) String senhaProfissional, Boolean identidadeConferida) {
  public AtualizacaoDadosPessoais(String nomeCompleto,String cpf,LocalDate dataNascimento,String emailContato,String telefone,String sexo,String endereco,Integer versao){this(nomeCompleto,cpf,dataNascimento,emailContato,telefone,sexo,endereco,versao,null,null);}
 }
 public record AtualizacaoContatoPaciente(@Size(max=20) String telefone, @NotNull @Min(0) Integer versao) {}
 public record PacienteCadastrado(@com.fasterxml.jackson.annotation.JsonProperty("patient") ModelosApi.Paciente paciente,@com.fasterxml.jackson.annotation.JsonProperty("activationToken") String codigoAtivacao,@com.fasterxml.jackson.annotation.JsonProperty("expiresAt") Instant expiraEm) {}
 public record AtivacaoConta(@NotBlank @Size(max=128) String token,@com.fasterxml.jackson.annotation.JsonProperty("password") @NotBlank @Size(min=12,max=72) String senha) {}
 public record ConfirmacaoSenha(@com.fasterxml.jackson.annotation.JsonProperty("password") @NotBlank @Size(max=72) String senha) {}
 public record CodigoAcesso(@com.fasterxml.jackson.annotation.JsonProperty("activationToken") String codigoAtivacao,@com.fasterxml.jackson.annotation.JsonProperty("expiresAt") Instant expiraEm) {}
 public record VinculoProfissional(@com.fasterxml.jackson.annotation.JsonProperty("professionalId") @NotNull UUID idProfissional) {}
 public record EntradaRegistroPressao(@NotNull UUID id,@com.fasterxml.jackson.annotation.JsonProperty("systolic") @Min(1) @Max(400) int sistolica,@com.fasterxml.jackson.annotation.JsonProperty("diastolic") @Min(1) @Max(400) int diastolica,@com.fasterxml.jackson.annotation.JsonProperty("pulse") @Min(1) @Max(300) Integer pulso,@com.fasterxml.jackson.annotation.JsonProperty("measuredAt") @NotNull Instant dataMedicao,@NotNull @Pattern(regexp="MANUAL|PROFESSIONAL|PRINTED_DIARY|OCR_CONFIRMED") String source,@com.fasterxml.jackson.annotation.JsonProperty("ocrDocumentId") UUID idDocumentoOcr,@com.fasterxml.jackson.annotation.JsonProperty("ocrConfirmed") Boolean ocrConfirmado) {}
 public record RegistroPressao(UUID id,@com.fasterxml.jackson.annotation.JsonProperty("patientId") UUID idPaciente,@com.fasterxml.jackson.annotation.JsonProperty("systolic") int sistolica,@com.fasterxml.jackson.annotation.JsonProperty("diastolic") int diastolica,@com.fasterxml.jackson.annotation.JsonProperty("pulse") Integer pulso,@com.fasterxml.jackson.annotation.JsonProperty("measuredAt") Instant dataMedicao,@com.fasterxml.jackson.annotation.JsonProperty("createdAt") Instant dataRegistro,@com.fasterxml.jackson.annotation.JsonProperty("syncedAt") Instant dataSincronizacao,String source,@com.fasterxml.jackson.annotation.JsonProperty("authorId") UUID idAutor,@com.fasterxml.jackson.annotation.JsonProperty("ocrDocumentId") UUID idDocumentoOcr, String authorName) {}
 public record EntradaMedicamento(@NotBlank @Size(max=160) String name,@com.fasterxml.jackson.annotation.JsonProperty("instruction") @NotBlank @Size(max=1000) String instrucaoProfissional,@com.fasterxml.jackson.annotation.JsonProperty("startsOn") @NotNull LocalDate inicioVigencia,@com.fasterxml.jackson.annotation.JsonProperty("endsOn") LocalDate fimVigencia,@com.fasterxml.jackson.annotation.JsonProperty("timeZone") @NotBlank String fusoHorario,@com.fasterxml.jackson.annotation.JsonProperty("schedules") @NotEmpty @Size(max=12) List<@Pattern(regexp="([01][0-9]|2[0-3]):[0-5][0-9]") String> horarios,@com.fasterxml.jackson.annotation.JsonProperty("version") Integer versao) {}
 public record EntradaAutorrelato(@NotNull UUID id,@com.fasterxml.jackson.annotation.JsonProperty("planId") @NotNull UUID idPlano,@com.fasterxml.jackson.annotation.JsonProperty("scheduledAt") @NotNull Instant horarioProgramado,@Pattern(regexp="TAKEN|NOT_TAKEN") @NotNull String status,@com.fasterxml.jackson.annotation.JsonProperty("reportedAt") @NotNull Instant dataAutorrelato) {}
 public record PerfilAtividade(@com.fasterxml.jackson.annotation.JsonProperty("mobility") @NotBlank @Size(max=300) String mobilidade,@com.fasterxml.jackson.annotation.JsonProperty("balance") @NotBlank @Size(max=300) String equilibrio,@com.fasterxml.jackson.annotation.JsonProperty("restrictions") @NotNull @Size(max=2000) String restricoes,@com.fasterxml.jackson.annotation.JsonProperty("professionalGuidance") @NotNull @Size(max=2000) String orientacoesProfissionais,@com.fasterxml.jackson.annotation.JsonProperty("approvedCatalogGroup") @Pattern(regexp="NAO_DEFINIDO|COM_RISCO_QUEDA_SENTADO|SEM_RISCO_QUEDA_EM_PE") String grupoCatalogoAprovado) {}
 public record EntradaAtividade(@NotNull UUID id,@NotBlank @Size(max=160) String type,@com.fasterxml.jackson.annotation.JsonProperty("durationMinutes") @Min(1) @Max(1440) int duracaoMinutos,@NotNull Instant occurredAt,@com.fasterxml.jackson.annotation.JsonProperty("notes") @Size(max=2000) String observacoes,@com.fasterxml.jackson.annotation.JsonProperty("feeling") @NotNull @Pattern(regexp="WELL|TIRED|UNWELL") String estadoInformado) {}
 public record EntradaDiario(@NotNull UUID id,@NotNull Instant occurredAt,@com.fasterxml.jackson.annotation.JsonProperty("systolic") @Min(1) @Max(400) Integer sistolica,@com.fasterxml.jackson.annotation.JsonProperty("diastolic") @Min(1) @Max(400) Integer diastolica,@com.fasterxml.jackson.annotation.JsonProperty("pulse") @Min(1) @Max(300) Integer pulso,@Size(max=2000) String medicationReport,@com.fasterxml.jackson.annotation.JsonProperty("notes") @Size(max=2000) String observacoes) {}
 public record EntradaConsulta(@NotNull UUID id,@NotNull Instant occurredAt,@com.fasterxml.jackson.annotation.JsonProperty("notes") @NotBlank @Size(max=4000) String observacoes,@com.fasterxml.jackson.annotation.JsonProperty("goals") @NotBlank @Size(max=2000) String objetivos,@com.fasterxml.jackson.annotation.JsonProperty("carePlan") @NotBlank @Size(max=4000) String planoCuidado) {}
 public record EntradaPulseira(@com.fasterxml.jackson.annotation.JsonProperty("label") @NotBlank @Size(max=160) String identificacao,@com.fasterxml.jackson.annotation.JsonProperty("serialNumber") @Size(max=160) String numeroSerie) {}
 public record EntradaConfiguracaoPulseira(@com.fasterxml.jackson.annotation.JsonProperty("schedules") @NotEmpty @Size(max=12) List<@Pattern(regexp="([01][0-9]|2[0-3]):[0-5][0-9]") String> horarios,@com.fasterxml.jackson.annotation.JsonProperty("adapter") @NotNull @Pattern(regexp="SIMULATED|HARDWARE") String adaptador) {}
}
